fn frame(t: i32) {
    host::display::clear(0x101014);
    host::display::draw_string(120, 40, "NOTIFY TESTER", 0xffffff, 2);

    host::display::fill_rect(156, 120, 200, 90, 0xdddddd);
    host::display::draw_string(202, 155, "BUZZ ME", 0x000000, 2);

    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    host::display::state_set(0, down);
    if down == 1 && prev == 0 {
        let px: i32 = host::display::pointer_x();
        let py: i32 = host::display::pointer_y();
        if px >= 156 && px < 356 && py >= 120 && py < 210 {
            let ok: i32 = host::agent::notify("Cartridge ping", "You tapped the buzz button.");
            if ok == 1 {
                host::display::state_set(1, host::display::state_get(1) + 1);
                host::display::state_set(3, t);
            } else {
                host::display::state_set(2, host::display::state_get(2) + 1);
            }
        }
    }

    host::display::draw_string(80, 270, "POSTED", 0x22bb44, 2);
    host::display::draw_number(80, 300, host::display::state_get(1), 0xffffff, 4);
    host::display::draw_string(320, 270, "DROPPED", 0xbb5533, 2);
    host::display::draw_number(320, 300, host::display::state_get(2), 0xffffff, 4);

    let last: i32 = host::display::state_get(3);
    let mut cool: i32 = 180 - (t - last);
    if last == 0 || cool < 0 {
        cool = 0;
    }
    host::display::draw_string(80, 400, "RATE LIMIT COOLDOWN", 0x888888, 1);
    host::display::fill_rect(80, 420, cool * 2, 10, 0xaa7700);
    host::display::draw_string(80, 450, "DROPS ARE NORMAL: PERMISSION-GATED", 0x556677, 1);
    host::display::draw_string(80, 464, "AND LIMITED TO ROUGHLY ONE PER 3S", 0x556677, 1);
    host::display::present();
}
